    blood_pressure: int;
    heart_rate: int;
}

class LabResults {
    total_cholesterol: int;
}

class Patient {
    patient_id: string;
    age: int;
    gender: string;
    vital_signs: VitalSigns;
    lab_results: LabResults;
}

let vitals := new VitalSigns {
    blood_pressure := 150,
    heart_rate     := 80,
};

let labs := new LabResults {
    total_cholesterol := 220,
};

let patient := new Patient {
    patient_id  := "PAT001",
    age         := 55,
    gender      := "M",
    vital_signs := vitals,
    lab_results := labs,
