## Complete Example — Parallel Workflow with Function

```bscript
import compute;

func process_item(item) {
    let result := run(item);
    return result;
}

let a := "input_a";
let b := "input_b";

let results := parallel [all] [{
    return process_item(a);
}, {
    return process_item(b);
}];

println(results[0]);
println(results[1]);
```
